  { to: '/',            icon: LayoutDashboard, label: 'Dashboard' },
  { to: '/projects',    icon: FolderGit2,      label: 'Projects' },
  { to: '/dependencies',icon: Package,         label: 'Dependencies' },
  { to: '/scans',       icon: Search,          label: 'Scans' },
  { to: '/findings',    icon: AlertTriangle,   label: 'Findings' },
  { to: '/remediations',icon: Wrench,          label: 'Remediations' },
  { to: '/artifacts',   icon: Database,        label: 'Artifacts' },
  { to: '/reports',     icon: FileText,        label: 'Reports' },
  { to: '/threat-intel',icon: Shield,          label: 'Threat Intel' },
]

export default function Sidebar() {
  const { pathname } = useLocation()

  return (
    <aside className="w-60 min-h-screen bg-gray-900 border-r border-gray-800 flex flex-col">
      {/* Logo */}
      <div className="px-5 py-5 border-b border-gray-800">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-sky-600 flex items-center justify-center flex-shrink-0">
            <Shield size={16} className="text-white" />
          </div>
          <div>
            <div className="text-sm font-bold text-white">SecureChain</div>
            <div className="text-xs text-gray-500">Supply Chain Security</div>
          </div>
        </div>
      </div>

      {/* Nav */}
      <nav className="flex-1 px-3 py-4 space-y-0.5">
        {NAV.map(({ to, icon: Icon, label }) => {
          const active = pathname === to || (to !== '/' && pathname.startsWith(to))
          return (
            <Link
              key={to}
              to={to}
              className={clsx(
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors',
                active
                  ? 'bg-sky-600/20 text-sky-400 border border-sky-700/30'
                  : 'text-gray-400 hover:text-gray-100 hover:bg-gray-800'
              )}
            >
              <Icon size={16} className="flex-shrink-0" />
              {label}
            </Link>
          )
        })}
      </nav>

      {/* Footer */}
      <div className="px-4 py-3 border-t border-gray-800">
        <p className="text-xs text-gray-600">v1.0.0 · SecureChain Platform</p>
      </div>
    </aside>
  )
}

import { type Severity, type ThreatType, type ScanStatus } from '../api/client'
import { SEVERITY_CONFIG, THREAT_LABELS, SCAN_STATUS_CONFIG } from '../lib/constants'
import clsx from 'clsx'

export function SeverityBadge({ severity }: { severity: Severity }) {
  const cfg = SEVERITY_CONFIG[severity] || SEVERITY_CONFIG.unknown
  return (
    <span className={clsx('badge font-semibold text-xs uppercase tracking-wide', cfg.bg, cfg.color)}>
      {cfg.label}
    </span>
  )
}

export function ThreatBadge({ type }: { type: ThreatType }) {
  const label = THREAT_LABELS[type] || type
  return (
    <span className="badge bg-gray-800 text-gray-300 border border-gray-700 text-xs">
      {label}
    </span>
  )
}

export function ScanStatusBadge({ status }: { status: ScanStatus }) {
  const cfg = SCAN_STATUS_CONFIG[status]
  return (
    <span className={clsx('inline-flex items-center gap-1.5 text-xs font-medium', cfg.color)}>
      {cfg.pulse ? (
        <span className="relative flex h-2 w-2">
          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75" />
          <span className="relative inline-flex rounded-full h-2 w-2 bg-sky-500" />
        </span>
      ) : (
        <span className="w-2 h-2 rounded-full bg-current" />
      )}
      {cfg.label}
    </span>
  )
}

export function RiskScore({ score }: { score: number }) {
  const color =
    score >= 75 ? 'text-red-400'
    : score >= 50 ? 'text-orange-400'
    : score >= 25 ? 'text-yellow-400'
    : 'text-green-400'
  const ring =
    score >= 75 ? 'stroke-red-500'
    : score >= 50 ? 'stroke-orange-500'
    : score >= 25 ? 'stroke-yellow-500'
    : 'stroke-green-500'

  const r = 20
  const circ = 2 * Math.PI * r
  const dash = circ * (score / 100)

  return (
    <div className="flex items-center gap-3">
      <svg width="52" height="52" viewBox="0 0 52 52">
        <circle cx="26" cy="26" r={r} fill="none" stroke="#1f2937" strokeWidth="5" />
        <circle
          cx="26" cy="26" r={r}
          fill="none"
          className={ring}
          strokeWidth="5"
          strokeDasharray={`${dash} ${circ}`}
          strokeLinecap="round"
          transform="rotate(-90 26 26)"
        />
        <text x="26" y="30" textAnchor="middle" className={clsx('text-xs font-bold fill-current', color)} fontSize="10">
          {score.toFixed(0)}
        </text>
      </svg>
      <div>
        <div className={clsx('font-bold text-lg', color)}>{score.toFixed(1)}</div>
        <div className="text-xs text-gray-500">Risk Score</div>
      </div>
    </div>
  )
}

export function StatCard({
  label,
  value,
  sub,
  icon,
  color = 'text-gray-100',
}: {
  label: string
  value: string | number
  sub?: string
  icon?: React.ReactNode
  color?: string
}) {
  return (
    <div className="card flex items-start justify-between gap-4">
      <div className="flex-1">
        <p className="text-xs text-gray-500 uppercase tracking-wide mb-1">{label}</p>
        <p className={clsx('text-3xl font-bold', color)}>{value}</p>
        {sub && <p className="text-xs text-gray-500 mt-1">{sub}</p>}
      </div>
      {icon && (
        <div className="w-10 h-10 rounded-lg bg-gray-800 flex items-center justify-center flex-shrink-0">
          {icon}
        </div>
      )}
    </div>
  )
}

export function EmptyState({ message, icon }: { message: string; icon?: React.ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      {icon && <div className="mb-3 text-gray-600">{icon}</div>}
      <p className="text-gray-500 text-sm">{message}</p>
    </div>
  )
}

export function Spinner() {
  return (
    <div className="flex items-center justify-center py-16">
      <div className="w-8 h-8 border-2 border-gray-700 border-t-sky-500 rounded-full animate-spin" />
    </div>
  )
}

export function PageHeader({
  title,
  subtitle,
  actions,
}: {
  title: string
  subtitle?: string
  actions?: React.ReactNode
}) {
  return (
    <div className="flex items-start justify-between mb-6">
      <div>
        <h1 className="text-xl font-bold text-white">{title}</h1>
        {subtitle && <p className="text-sm text-gray-400 mt-0.5">{subtitle}</p>}
      </div>
      {actions && <div className="flex items-center gap-2 flex-shrink-0">{actions}</div>}
    </div>
  )
}

export function ErrorBanner({ message }: { message: string }) {
  return (
    <div className="bg-red-900/30 border border-red-800 rounded-lg px-4 py-3 text-sm text-red-300 mb-4">
      ⚠️ {message}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts'
import {
  Shield, AlertTriangle, Package, Scan, Wrench, TrendingUp,
  FolderGit2, CheckCircle2, XCircle
} from 'lucide-react'
import { getDashboard, type DashboardStats } from '../api/client'
import { StatCard, ScanStatusBadge, SeverityBadge, Spinner, ErrorBanner } from '../components/ui'
import { formatDate } from '../lib/constants'

const PIE_COLORS = ['#ef4444', '#f97316', '#eab308', '#3b82f6', '#22c55e', '#6b7280']

const CHART_STYLE = {
  fontSize: 11,
  fill: '#94a3b8',
}

export default function Dashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    getDashboard()
      .then(setStats)
      .catch(() => setError('Failed to load dashboard. Is the backend running?'))
      .finally(() => setLoading(false))
  }, [])

  if (loading) return <Spinner />
  if (error) return <ErrorBanner message={error} />
  if (!stats) return null

  const severityData = Object.entries(stats.severity_distribution).map(([k, v]) => ({
    name: k.charAt(0).toUpperCase() + k.slice(1), value: v,
  }))

  const threatData = Object.entries(stats.threat_type_distribution)
    .sort((a, b) => b[1] - a[1])
    .map(([k, v]) => ({
      name: k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
      value: v,
    }))

  const ecoData = Object.entries(stats.ecosystem_distribution).map(([k, v]) => ({
    name: k.toUpperCase(), value: v,
  }))

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-xl font-bold text-white">Dashboard</h1>
        <p className="text-sm text-gray-400 mt-0.5">Supply chain security overview</p>
      </div>

      {/* Stat cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Total Projects"
          value={stats.total_projects}
          sub={`${stats.active_projects} active`}
          icon={<FolderGit2 size={18} className="text-sky-400" />}
          color="text-sky-300"
        />
        <StatCard
          label="Dependencies"
          value={stats.total_dependencies.toLocaleString()}
          icon={<Package size={18} className="text-purple-400" />}
          color="text-purple-300"
        />
        <StatCard
          label="Critical Findings"
          value={stats.critical_findings}
          sub={`${stats.total_findings} total`}
          icon={<AlertTriangle size={18} className="text-red-400" />}
          color="text-red-300"
        />
        <StatCard
          label="Open Remediations"
          value={stats.open_remediations}
          sub={`${stats.resolved_remediations} resolved`}
          icon={<Wrench size={18} className="text-orange-400" />}
          color="text-orange-300"
        />
        <StatCard
          label="Avg Risk Score"
          value={stats.avg_risk_score.toFixed(1)}
          sub="Across all projects"
          icon={<TrendingUp size={18} className="text-yellow-400" />}
          color={stats.avg_risk_score >= 50 ? 'text-red-400' : 'text-yellow-300'}
        />
        <StatCard
          label="Total Scans"
          value={stats.total_scans}
          icon={<Shield size={18} className="text-green-400" />}
          color="text-green-300"
        />
        <StatCard
          label="Total Findings"
          value={stats.total_findings}
          icon={<AlertTriangle size={18} className="text-orange-400" />}
        />
        <StatCard
          label="Resolved"
          value={stats.resolved_remediations}
          icon={<CheckCircle2 size={18} className="text-green-400" />}
          color="text-green-300"
        />
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Severity Distribution */}
        <div className="card">
          <h3 className="text-sm font-semibold text-gray-300 mb-4">Severity Distribution</h3>
          {severityData.length === 0 ? (
            <p className="text-gray-500 text-sm text-center py-6">No findings yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={200}>
              <PieChart>
                <Pie data={severityData} cx="50%" cy="50%" innerRadius={55} outerRadius={80}
                  dataKey="value" labelLine={false}>
                  {severityData.map((_, i) => (
                    <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ background: '#1f2937', border: '1px solid #374151', borderRadius: 8 }}
                  itemStyle={{ color: '#e2e8f0' }} />
                <Legend wrapperStyle={CHART_STYLE} />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Threat Type Breakdown */}
        <div className="card lg:col-span-2">
          <h3 className="text-sm font-semibold text-gray-300 mb-4">Threat Type Breakdown</h3>
          {threatData.length === 0 ? (
            <p className="text-gray-500 text-sm text-center py-6">No findings yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={threatData} layout="vertical" margin={{ left: 20, right: 20 }}>
                <XAxis type="number" tick={CHART_STYLE} axisLine={false} tickLine={false} />
                <YAxis type="category" dataKey="name" tick={{ ...CHART_STYLE, fontSize: 10 }}
                  width={140} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ background: '#1f2937', border: '1px solid #374151', borderRadius: 8 }}
                  itemStyle={{ color: '#e2e8f0' }} />
                <Bar dataKey="value" fill="#0ea5e9" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>

      {/* Ecosystem & Recent Scans */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Ecosystem Distribution */}
        <div className="card">
          <h3 className="text-sm font-semibold text-gray-300 mb-4">Dependencies by Ecosystem</h3>
          {ecoData.length === 0 ? (
            <p className="text-gray-500 text-sm text-center py-6">No dependencies yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={ecoData}>
                <XAxis dataKey="name" tick={CHART_STYLE} axisLine={false} tickLine={false} />
                <YAxis tick={CHART_STYLE} axisLine={false} tickLine={false} />
                <Tooltip contentStyle={{ background: '#1f2937', border: '1px solid #374151', borderRadius: 8 }}
                  itemStyle={{ color: '#e2e8f0' }} />
                <Bar dataKey="value" fill="#7c3aed" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Recent Scans */}
        <div className="card">
          <h3 className="text-sm font-semibold text-gray-300 mb-4">Recent Scans</h3>
          {stats.recent_scans.length === 0 ? (
            <p className="text-gray-500 text-sm text-center py-6">No scans yet</p>
          ) : (
            <div className="space-y-2">
              {stats.recent_scans.map(scan => (
                <Link
                  key={scan.id}
                  to={`/scans`}
                  className="flex items-center justify-between p-3 bg-gray-800/50 rounded-lg hover:bg-gray-800 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <ScanStatusBadge status={scan.status} />
                    <div>
                      <p className="text-xs text-gray-300 font-medium">Scan #{scan.id} · Project {scan.project_id}</p>
                      <p className="text-xs text-gray-500">{formatDate(scan.started_at)}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-red-400 font-medium">{scan.critical_count} critical</p>
                    <p className="text-xs text-gray-500">Score: {scan.risk_score.toFixed(1)}</p>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Supply Chain Workflow Diagram */}
      <div className="card">
        <h3 className="text-sm font-semibold text-gray-300 mb-4">Supply Chain Workflow</h3>
        <div className="flex items-center justify-between gap-2 overflow-x-auto pb-2">
          {[
            { icon: '👨‍💻', label: 'Developer', sub: 'Code commit' },
            { icon: '📁', label: 'Source Repo', sub: 'Version control' },
            { icon: '🔨', label: 'Build', sub: 'CI/CD pipeline' },
            { icon: '📦', label: 'Dependencies', sub: 'Package resolution' },
            { icon: '🔍', label: 'Security Scan', sub: 'Vulnerability check' },
            { icon: '📚', label: 'Artifact Repo', sub: 'Signed & stored' },
          ].map((step, i) => (
            <div key={i} className="flex items-center gap-2 flex-shrink-0">
              <div className="flex flex-col items-center gap-1 min-w-[90px]">
                <div className="w-12 h-12 rounded-xl bg-gray-800 flex items-center justify-center text-2xl">
                  {step.icon}
                </div>
                <span className="text-xs font-medium text-gray-300">{step.label}</span>
                <span className="text-xs text-gray-600 text-center">{step.sub}</span>
              </div>
              {i < 5 && (
                <div className="text-gray-700 text-lg mx-1">→</div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { Plus, Trash2, FolderGit2, ChevronRight, ExternalLink } from 'lucide-react'
import {
  getProjects, createProject, deleteProject,
  type Project
} from '../api/client'
import {
  PageHeader, Spinner, ErrorBanner, EmptyState, RiskScore
} from '../components/ui'
import { ECOSYSTEM_ICONS, formatDate } from '../lib/constants'
import clsx from 'clsx'

const ECOSYSTEMS = ['unknown', 'npm', 'pypi', 'maven', 'nuget', 'rubygems', 'go', 'cargo', 'docker']

export default function Projects() {
  const [projects, setProjects] = useState<Project[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [showForm, setShowForm] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [form, setForm] = useState({
    name: '', description: '', repo_url: '', ecosystem: 'unknown',
    owner: '', team: '', default_branch: 'main',
  })

  const load = () => {
    setLoading(true)
    getProjects()
      .then(setProjects)
      .catch(() => setError('Failed to load projects'))
      .finally(() => setLoading(false))
  }

  useEffect(load, [])

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!form.name.trim()) return
    setSubmitting(true)
    try {
      await createProject(form as Partial<Project>)
      setShowForm(false)
      setForm({ name: '', description: '', repo_url: '', ecosystem: 'unknown', owner: '', team: '', default_branch: 'main' })
      load()
    } catch {
      setError('Failed to create project')
    } finally {
      setSubmitting(false)
    }
  }

  const handleDelete = async (id: number, name: string) => {
    if (!confirm(`Delete project "${name}"? This cannot be undone.`)) return
    await deleteProject(id)
    load()
  }

  return (
    <div className="p-6">
      <PageHeader
        title="Projects"
        subtitle={`${projects.length} registered project${projects.length !== 1 ? 's' : ''}`}
        actions={
          <button onClick={() => setShowForm(s => !s)} className="btn-primary">
            <Plus size={15} /> New Project
          </button>
        }
      />

      {error && <ErrorBanner message={error} />}

      {/* Create Form */}
      {showForm && (
        <div className="card mb-6">
          <h3 className="text-sm font-semibold text-gray-200 mb-4">Register New Project</h3>
          <form onSubmit={handleCreate} className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="md:col-span-2">
              <label className="block text-xs text-gray-400 mb-1">Project Name *</label>
              <input className="input" placeholder="my-service"
                value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required />
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs text-gray-400 mb-1">Description</label>
              <input className="input" placeholder="Brief project description"
                value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Repository URL</label>
              <input className="input" placeholder="https://github.com/org/repo"
                value={form.repo_url} onChange={e => setForm(f => ({ ...f, repo_url: e.target.value }))} />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Ecosystem</label>
              <select className="select" value={form.ecosystem}
                onChange={e => setForm(f => ({ ...f, ecosystem: e.target.value }))}>
                {ECOSYSTEMS.map(e => (
                  <option key={e} value={e}>
                    {ECOSYSTEM_ICONS[e]} {e.toUpperCase()}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Owner</label>
              <input className="input" placeholder="john.doe"
                value={form.owner} onChange={e => setForm(f => ({ ...f, owner: e.target.value }))} />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Team</label>
              <input className="input" placeholder="platform-security"
                value={form.team} onChange={e => setForm(f => ({ ...f, team: e.target.value }))} />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Default Branch</label>
              <input className="input" placeholder="main"
                value={form.default_branch} onChange={e => setForm(f => ({ ...f, default_branch: e.target.value }))} />
            </div>
            <div className="md:col-span-2 flex gap-2 justify-end pt-2">
              <button type="button" className="btn-secondary" onClick={() => setShowForm(false)}>Cancel</button>
              <button type="submit" className="btn-primary" disabled={submitting}>
                {submitting ? 'Creating…' : 'Create Project'}
              </button>
            </div>
          </form>
        </div>
      )}

      {loading ? <Spinner /> : projects.length === 0 ? (
        <EmptyState
          message="No projects yet. Click 'New Project' to register your first project."
          icon={<FolderGit2 size={40} />}
        />
      ) : (
        <div className="space-y-3">
          {projects.map(p => (
            <div key={p.id} className="card hover:border-gray-700 transition-colors group">
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-lg">{ECOSYSTEM_ICONS[p.ecosystem]}</span>
                    <Link
                      to={`/projects/${p.id}`}
                      className="text-sm font-semibold text-white hover:text-sky-400 transition-colors"
                    >
                      {p.name}
                    </Link>
                    {!p.is_active && (
                      <span className="badge bg-gray-800 text-gray-500 border border-gray-700 text-xs">Inactive</span>
                    )}
                  </div>
                  {p.description && (
                    <p className="text-xs text-gray-400 mb-2 truncate">{p.description}</p>
                  )}
                  <div className="flex flex-wrap gap-3 text-xs text-gray-500">
                    {p.owner && <span>👤 {p.owner}</span>}
                    {p.team && <span>🏷️ {p.team}</span>}
                    <span>📅 {formatDate(p.created_at)}</span>
                    {p.repo_url && (
                      <a href={p.repo_url} target="_blank" rel="noreferrer"
                        className="inline-flex items-center gap-1 text-sky-500 hover:text-sky-400">
                        <ExternalLink size={11} /> Repo
                      </a>
                    )}
                  </div>
                </div>

                {/* Stats */}
                <div className="flex items-center gap-6 flex-shrink-0">
                  <div className="text-right">
                    <p className="text-xs text-gray-500">Dependencies</p>
                    <p className="text-base font-bold text-white">{p.total_deps ?? 0}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-gray-500">Critical</p>
                    <p className={clsx('text-base font-bold', (p.critical_findings ?? 0) > 0 ? 'text-red-400' : 'text-green-400')}>
                      {p.critical_findings ?? 0}
                    </p>
                  </div>
                  <RiskScore score={p.risk_score ?? 0} />
                  <div className="flex items-center gap-1">
                    <Link to={`/projects/${p.id}`} className="btn-secondary text-xs py-1.5 px-3">
                      <ChevronRight size={13} />
                    </Link>
                    <button
                      onClick={() => handleDelete(p.id, p.name)}
                      className="p-2 rounded-lg text-gray-600 hover:text-red-400 hover:bg-red-900/20 transition-colors"
                    >
                      <Trash2 size={13} />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useParams, Link, useNavigate } from 'react-router-dom'
import { ArrowLeft, Play, Package, FileText, Hammer, Database, AlertTriangle } from 'lucide-react'
import {
  getProject, getScans, triggerScan, getDependencies, getBuilds, getArtifacts,
  type Project, type Scan, type Dependency, type Build, type Artifact
} from '../api/client'
import {
  Spinner, ErrorBanner, ScanStatusBadge, SeverityBadge, RiskScore, PageHeader
} from '../components/ui'
import { formatDate, ECOSYSTEM_ICONS } from '../lib/constants'
import clsx from 'clsx'

type Tab = 'overview' | 'dependencies' | 'scans' | 'builds' | 'artifacts'

export default function ProjectDetail() {
  const { id } = useParams<{ id: string }>()
  const projectId = Number(id)
  const navigate = useNavigate()

  const [project, setProject] = useState<Project | null>(null)
  const [scans, setScans] = useState<Scan[]>([])
  const [deps, setDeps] = useState<Dependency[]>([])
  const [builds, setBuilds] = useState<Build[]>([])
  const [artifacts, setArtifacts] = useState<Artifact[]>([])
  const [tab, setTab] = useState<Tab>('overview')
  const [loading, setLoading] = useState(true)
  const [scanning, setScanning] = useState(false)
  const [error, setError] = useState('')

  const loadAll = async () => {
    try {
      const [p, s, d, b, a] = await Promise.all([
        getProject(projectId),
        getScans(projectId),
        getDependencies(projectId),
        getBuilds(projectId),
        getArtifacts(projectId),
      ])
      setProject(p); setScans(s); setDeps(d); setBuilds(b); setArtifacts(a)
    } catch {
      setError('Failed to load project data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { loadAll() }, [projectId])

  const handleScan = async () => {
    setScanning(true)
    try {
      await triggerScan(projectId, { scan_type: 'full', triggered_by: 'manual' })
      // Poll until completed
      setTimeout(async () => {
        const updated = await getScans(projectId)
        setScans(updated)
        setScanning(false)
        const p = await getProject(projectId)
        setProject(p)
      }, 3000)
    } catch {
      setError('Scan failed to start')
      setScanning(false)
    }
  }

  if (loading) return <Spinner />
  if (!project) return <ErrorBanner message="Project not found" />

  const latestScan = scans[0]
  const TABS: { key: Tab; label: string; count?: number }[] = [
    { key: 'overview',     label: 'Overview' },
    { key: 'dependencies', label: 'Dependencies', count: deps.length },
    { key: 'scans',        label: 'Scans', count: scans.length },
    { key: 'builds',       label: 'Builds', count: builds.length },
    { key: 'artifacts',    label: 'Artifacts', count: artifacts.length },
  ]

  return (
    <div className="p-6">
      {/* Header */}
      <div className="flex items-start gap-4 mb-6">
        <button onClick={() => navigate('/projects')}
          className="p-2 rounded-lg text-gray-500 hover:text-gray-300 hover:bg-gray-800 transition-colors mt-0.5">
          <ArrowLeft size={16} />
        </button>
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-xl">{ECOSYSTEM_ICONS[project.ecosystem]}</span>
            <h1 className="text-xl font-bold text-white">{project.name}</h1>
          </div>
          {project.description && (
            <p className="text-sm text-gray-400">{project.description}</p>
          )}
          <div className="flex flex-wrap gap-3 text-xs text-gray-500 mt-2">
            {project.owner && <span>👤 {project.owner}</span>}
            {project.team && <span>🏷️ {project.team}</span>}
            <span>Branch: {project.default_branch}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {project.risk_score !== undefined && <RiskScore score={project.risk_score} />}
          <button
            onClick={handleScan}
            disabled={scanning}
            className="btn-primary"
          >
            {scanning ? (
              <><span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> Scanning…</>
            ) : (
              <><Play size={14} /> Run Scan</>
            )}
          </button>
        </div>
      </div>

      {error && <ErrorBanner message={error} />}

      {/* Tabs */}
      <div className="flex gap-1 border-b border-gray-800 mb-6">
        {TABS.map(t => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={clsx(
              'px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px',
              tab === t.key
                ? 'border-sky-500 text-sky-400'
                : 'border-transparent text-gray-500 hover:text-gray-300'
            )}
          >
            {t.label}
            {t.count !== undefined && (
              <span className="ml-1.5 text-xs bg-gray-800 text-gray-400 px-1.5 py-0.5 rounded-full">
                {t.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      {tab === 'overview' && (
        <div className="space-y-4">
          {/* Latest scan summary */}
          {latestScan ? (
            <div className="card">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-gray-200">Latest Scan #{latestScan.id}</h3>
                <ScanStatusBadge status={latestScan.status} />
              </div>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                {[
                  { label: 'Critical', value: latestScan.critical_count, color: 'text-red-400' },
                  { label: 'High', value: latestScan.high_count, color: 'text-orange-400' },
                  { label: 'Medium', value: latestScan.medium_count, color: 'text-yellow-400' },
                  { label: 'Low', value: latestScan.low_count, color: 'text-blue-400' },
                  { label: 'Deps Scanned', value: latestScan.total_deps_scanned, color: 'text-gray-300' },
                ].map(item => (
                  <div key={item.label} className="text-center">
                    <p className={clsx('text-2xl font-bold', item.color)}>{item.value}</p>
                    <p className="text-xs text-gray-500">{item.label}</p>
                  </div>
                ))}
              </div>
              {latestScan.status === 'completed' && (
                <div className="mt-4 flex gap-2">
                  <Link to={`/projects/${projectId}/report`} className="btn-secondary text-xs">
                    <FileText size={13} /> View Report
                  </Link>
                  <Link
                    to={`/scans?project=${projectId}&scan=${latestScan.id}`}
                    className="btn-secondary text-xs"
                  >
                    <AlertTriangle size={13} /> View Findings
                  </Link>
                </div>
              )}
            </div>
          ) : (
            <div className="card text-center py-10">
              <p className="text-gray-500 text-sm mb-3">No scans yet for this project.</p>
              <button onClick={handleScan} className="btn-primary mx-auto">
                <Play size={14} /> Run First Scan
              </button>
            </div>
          )}

          {/* Quick stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[
              { icon: <Package size={18} className="text-purple-400" />, label: 'Dependencies', value: deps.length },
              { icon: <Hammer size={18} className="text-sky-400" />, label: 'Builds', value: builds.length },
              { icon: <Database size={18} className="text-green-400" />, label: 'Artifacts', value: artifacts.length },
              { icon: <AlertTriangle size={18} className="text-yellow-400" />, label: 'Scans', value: scans.length },
            ].map(item => (
              <div key={item.label} className="card flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg bg-gray-800 flex items-center justify-center">
                  {item.icon}
                </div>
                <div>
                  <p className="text-xs text-gray-500">{item.label}</p>
                  <p className="text-lg font-bold text-white">{item.value}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === 'dependencies' && (
        <DepsTab deps={deps} projectId={projectId} onRefresh={loadAll} />
      )}

      {tab === 'scans' && (
        <div className="space-y-2">
          {scans.length === 0 ? (
            <p className="text-gray-500 text-sm text-center py-10">No scans yet</p>
          ) : (
            scans.map(scan => (
              <div key={scan.id} className="card flex items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <ScanStatusBadge status={scan.status} />
                  <div>
                    <p className="text-sm font-medium text-gray-200">Scan #{scan.id}</p>
                    <p className="text-xs text-gray-500">{formatDate(scan.started_at)}</p>
                  </div>
                </div>
                <div className="flex gap-4 text-sm">
                  <span className="text-red-400">{scan.critical_count} critical</span>
                  <span className="text-orange-400">{scan.high_count} high</span>
                  <span className="text-gray-400">Risk: {scan.risk_score.toFixed(1)}</span>
                </div>
                {scan.status === 'completed' && (
                  <Link
                    to={`/scans?project=${projectId}&scan=${scan.id}`}
                    className="btn-secondary text-xs"
                  >
                    View Findings
                  </Link>
                )}
              </div>
            ))
          )}
        </div>
      )}

      {tab === 'builds' && (
        <BuildsTab builds={builds} />
      )}

      {tab === 'artifacts' && (
        <ArtifactsTab artifacts={artifacts} />
      )}
    </div>
  )
}

