function DepsTab({ deps, projectId, onRefresh }: { deps: Dependency[]; projectId: number; onRefresh: () => void }) {
  const [showAdd, setShowAdd] = useState(false)
  const [form, setForm] = useState({ name: '', version: '', ecosystem: 'npm', is_direct: true, is_dev: false, license: '' })
  const { addDependency } = require('../api/client')

  const handle = async (e: React.FormEvent) => {
    e.preventDefault()
    await addDependency(projectId, form)
    setShowAdd(false)
    onRefresh()
  }

  return (
    <div>
      <div className="flex justify-end mb-3">
        <button onClick={() => setShowAdd(s => !s)} className="btn-secondary text-xs">
          <Package size={13} /> Add Dependency
        </button>
      </div>
      {showAdd && (
        <div className="card mb-4">
          <form onSubmit={handle} className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div>
              <label className="text-xs text-gray-400 block mb-1">Name</label>
              <input className="input" placeholder="lodash" required
                value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} />
            </div>
            <div>
              <label className="text-xs text-gray-400 block mb-1">Version</label>
              <input className="input" placeholder="4.17.21" required
                value={form.version} onChange={e => setForm(f => ({ ...f, version: e.target.value }))} />
            </div>
            <div>
              <label className="text-xs text-gray-400 block mb-1">Ecosystem</label>
              <select className="select" value={form.ecosystem}
                onChange={e => setForm(f => ({ ...f, ecosystem: e.target.value }))}>
                {['npm','pypi','maven','nuget','go','cargo','docker'].map(e => (
                  <option key={e} value={e}>{ECOSYSTEM_ICONS[e]} {e}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="text-xs text-gray-400 block mb-1">License</label>
              <input className="input" placeholder="MIT"
                value={form.license} onChange={e => setForm(f => ({ ...f, license: e.target.value }))} />
            </div>
            <div className="flex items-center gap-4 col-span-2">
              <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                <input type="checkbox" checked={form.is_direct}
                  onChange={e => setForm(f => ({ ...f, is_direct: e.target.checked }))}
                  className="rounded bg-gray-700 border-gray-600" />
                Direct dependency
              </label>
              <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                <input type="checkbox" checked={form.is_dev}
                  onChange={e => setForm(f => ({ ...f, is_dev: e.target.checked }))}
                  className="rounded bg-gray-700 border-gray-600" />
                Dev dependency
              </label>
            </div>
            <div className="col-span-2 flex gap-2 justify-end">
              <button type="button" className="btn-secondary text-xs" onClick={() => setShowAdd(false)}>Cancel</button>
              <button type="submit" className="btn-primary text-xs">Add</button>
            </div>
          </form>
        </div>
      )}
      {deps.length === 0 ? (
        <p className="text-gray-500 text-sm text-center py-10">No dependencies recorded</p>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-800">
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">Package</th>
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">Version</th>
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">Ecosystem</th>
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">Type</th>
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">License</th>
                <th className="text-left py-2 px-3 text-xs text-gray-500 font-medium">Hash</th>
              </tr>
            </thead>
            <tbody>
              {deps.map(d => (
                <tr key={d.id} className="table-row">
                  <td className="py-2 px-3 font-mono text-xs text-sky-400">{d.name}</td>
                  <td className="py-2 px-3 text-xs text-gray-300">{d.version}</td>
                  <td className="py-2 px-3 text-xs">
                    {ECOSYSTEM_ICONS[d.ecosystem]} {d.ecosystem}
                  </td>
                  <td className="py-2 px-3 text-xs text-gray-400">
                    {d.is_direct ? '📍 Direct' : `↗ Trans. (d${d.depth})`}
                    {d.is_dev && <span className="ml-1 text-gray-600">[dev]</span>}
                  </td>
                  <td className="py-2 px-3 text-xs text-gray-400">{d.license || '—'}</td>
                  <td className="py-2 px-3">
                    {d.package_hash ? (
                      <span className="font-mono text-xs text-green-500" title={d.package_hash}>
                        ✓ {d.package_hash.slice(0, 8)}…
                      </span>
