function BuildsTab({ builds }: { builds: Build[] }) {
  if (builds.length === 0) return <p className="text-gray-500 text-sm text-center py-10">No builds recorded</p>
  return (
    <div className="space-y-2">
      {builds.map(b => (
        <div key={b.id} className="card flex items-center justify-between gap-4">
          <div>
            <p className="text-sm font-medium text-gray-200">Build #{b.build_number}</p>
            <p className="text-xs text-gray-500">
              {b.branch} · {b.commit_sha?.slice(0, 7) || '—'} · {formatDate(b.started_at)}
            </p>
          </div>
          <div className="flex items-center gap-4 text-xs">
            {b.secrets_detected && <span className="text-pink-400">🔑 Secrets</span>}
            {b.tampered && <span className="text-red-400">⚠ Tampered</span>}
            {!b.provenance && <span className="text-yellow-600">No Provenance</span>}
