import { useEffect, useState, useCallback } from 'react'
import { useSearchParams } from 'react-router-dom'
import { Filter, AlertTriangle } from 'lucide-react'
import { getProjects, getScans, getFindings, type Project, type Scan, type Finding } from '../api/client'
import { SeverityBadge, ThreatBadge, ScanStatusBadge, Spinner, ErrorBanner, PageHeader } from '../components/ui'
import { THREAT_LABELS, formatDate } from '../lib/constants'
import clsx from 'clsx'

const SEVERITIES = ['critical', 'high', 'medium', 'low']
const THREATS = [
  'dependency_confusion', 'malicious_package', 'artifact_tampering',
  'build_compromise', 'secret_leakage', 'supply_chain_attack', 'cve',
]

export default function ScansPage() {
  const [searchParams] = useSearchParams()
  const defaultProject = searchParams.get('project')
  const defaultScan = searchParams.get('scan')

  const [projects, setProjects] = useState<Project[]>([])
  const [scans, setScans] = useState<Scan[]>([])
  const [findings, setFindings] = useState<Finding[]>([])
  const [selectedProject, setSelectedProject] = useState<string>(defaultProject || '')
  const [selectedScan, setSelectedScan] = useState<string>(defaultScan || '')
  const [severityFilter, setSeverityFilter] = useState('')
  const [threatFilter, setThreatFilter] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    getProjects().then(setProjects).catch(() => setError('Failed to load projects'))
  }, [])

  useEffect(() => {
    if (!selectedProject) return
    getScans(Number(selectedProject))
      .then(s => {
        setScans(s)
        if (!selectedScan && s[0]) setSelectedScan(String(s[0].id))
      })
      .catch(() => setError('Failed to load scans'))
  }, [selectedProject])

  useEffect(() => {
    if (!selectedProject || !selectedScan) return
    setLoading(true)
    setFindings([])
    getFindings(Number(selectedProject), Number(selectedScan), {
      severity: severityFilter || undefined,
      threat_type: threatFilter || undefined,
    })
      .then(setFindings)
      .catch(() => setError('Failed to load findings'))
      .finally(() => setLoading(false))
  }, [selectedProject, selectedScan, severityFilter, threatFilter])

  const currentScan = scans.find(s => String(s.id) === selectedScan)

  return (
    <div className="p-6">
      <PageHeader
        title="Security Scans"
        subtitle="View scan results and vulnerability findings"
      />

      {error && <ErrorBanner message={error} />}

      {/* Selectors */}
      <div className="card mb-4">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
          <div>
            <label className="text-xs text-gray-400 block mb-1">Project</label>
            <select className="select" value={selectedProject}
              onChange={e => { setSelectedProject(e.target.value); setSelectedScan(''); setScans([]) }}>
              <option value="">— Select Project —</option>
              {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs text-gray-400 block mb-1">Scan</label>
            <select className="select" value={selectedScan}
              onChange={e => setSelectedScan(e.target.value)} disabled={!scans.length}>
              <option value="">— Select Scan —</option>
              {scans.map(s => (
                <option key={s.id} value={s.id}>
                  Scan #{s.id} · {s.status} · {new Date(s.started_at).toLocaleDateString()}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-xs text-gray-400 block mb-1">Severity Filter</label>
            <select className="select" value={severityFilter}
              onChange={e => setSeverityFilter(e.target.value)}>
              <option value="">All Severities</option>
              {SEVERITIES.map(s => <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1)}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs text-gray-400 block mb-1">Threat Type</label>
            <select className="select" value={threatFilter}
              onChange={e => setThreatFilter(e.target.value)}>
              <option value="">All Threats</option>
              {THREATS.map(t => <option key={t} value={t}>{THREAT_LABELS[t as keyof typeof THREAT_LABELS]}</option>)}
            </select>
          </div>
        </div>
      </div>

      {/* Scan Summary */}
      {currentScan && (
        <div className="card mb-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold text-gray-200">
              Scan #{currentScan.id} Summary
            </h3>
            <ScanStatusBadge status={currentScan.status} />
          </div>
          <div className="grid grid-cols-3 md:grid-cols-6 gap-3 text-center">
            {[
              { label: 'Critical', value: currentScan.critical_count, color: 'text-red-400' },
              { label: 'High', value: currentScan.high_count, color: 'text-orange-400' },
              { label: 'Medium', value: currentScan.medium_count, color: 'text-yellow-400' },
              { label: 'Low', value: currentScan.low_count, color: 'text-blue-400' },
              { label: 'Deps Scanned', value: currentScan.total_deps_scanned, color: 'text-gray-300' },
              { label: 'Risk Score', value: currentScan.risk_score.toFixed(1), color: currentScan.risk_score >= 50 ? 'text-red-400' : 'text-green-400' },
            ].map(item => (
              <div key={item.label}>
                <p className={clsx('text-2xl font-bold', item.color)}>{item.value}</p>
                <p className="text-xs text-gray-500">{item.label}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Findings Table */}
      {!selectedProject ? (
        <div className="card text-center py-12">
          <AlertTriangle size={36} className="text-gray-700 mx-auto mb-3" />
          <p className="text-gray-500">Select a project and scan to view findings</p>
        </div>
      ) : loading ? <Spinner /> : findings.length === 0 ? (
        <div className="card text-center py-12">
          <p className="text-gray-500">
            {selectedScan ? 'No findings match your filters' : 'Select a scan to view findings'}
          </p>
        </div>
      ) : (
        <div className="card overflow-hidden p-0">
          <div className="px-5 py-3 border-b border-gray-800 flex items-center justify-between">
            <h3 className="text-sm font-semibold text-gray-200">
              {findings.length} Finding{findings.length !== 1 ? 's' : ''}
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-800">
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Severity</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Threat Type</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Title</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Package</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">CVE</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">CVSS</th>
                  <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Fix</th>
                </tr>
              </thead>
              <tbody>
                {findings.map(f => (
                  <FindingRow key={f.id} finding={f} />
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

function FindingRow({ finding: f }: { finding: Finding }) {
  const [expanded, setExpanded] = useState(false)
  return (
    <>
      <tr
        className="table-row cursor-pointer"
        onClick={() => setExpanded(e => !e)}
      >
        <td className="py-2.5 px-4"><SeverityBadge severity={f.severity} /></td>
        <td className="py-2.5 px-4"><ThreatBadge type={f.threat_type} /></td>
        <td className="py-2.5 px-4 text-xs text-gray-200 max-w-xs">
          <div className="truncate">{f.title}</div>
        </td>
        <td className="py-2.5 px-4 font-mono text-xs text-sky-400">
          {f.affected_package}
          {f.affected_version && <span className="text-gray-500">@{f.affected_version}</span>}
        </td>
        <td className="py-2.5 px-4 text-xs">
          {f.cve_id ? (
            <a
              href={`https://nvd.nist.gov/vuln/detail/${f.cve_id}`}
              target="_blank" rel="noreferrer"
              className="text-sky-500 hover:text-sky-400 underline"
              onClick={e => e.stopPropagation()}
            >
              {f.cve_id}
            </a>
          ) : '—'}
        </td>
        <td className="py-2.5 px-4 text-xs">
          {f.cvss_score !== undefined && f.cvss_score !== null ? (
            <span className={clsx('font-mono font-semibold',
              f.cvss_score >= 9 ? 'text-red-400' :
              f.cvss_score >= 7 ? 'text-orange-400' :
              f.cvss_score >= 4 ? 'text-yellow-400' : 'text-gray-400'
            )}>
              {f.cvss_score.toFixed(1)}
            </span>
          ) : '—'}
        </td>
        <td className="py-2.5 px-4 text-xs text-green-400">
          {f.fixed_in_version ? `→ ${f.fixed_in_version}` : '—'}
        </td>
      </tr>
      {expanded && (
        <tr className="bg-gray-800/30">
          <td colSpan={7} className="px-4 py-3">
            <div className="text-xs text-gray-300 space-y-1.5">
              {f.description && <p>{f.description}</p>}
              {f.evidence && (
                <details className="mt-2">
                  <summary className="cursor-pointer text-gray-500 hover:text-gray-400">Evidence</summary>
                  <pre className="mt-1 bg-gray-900 rounded p-2 text-xs overflow-x-auto">
                    {JSON.stringify(f.evidence, null, 2)}
                  </pre>
                </details>
              )}
            </div>
          </td>
        </tr>
      )}
    </>
  )
}

import { useEffect, useState } from 'react'
import { Package, Search, ExternalLink, ShieldAlert } from 'lucide-react'
import { getProjects, getDependencies, type Project, type Dependency } from '../api/client'
import { PageHeader, Spinner, ErrorBanner } from '../components/ui'
import { ECOSYSTEM_ICONS } from '../lib/constants'

export default function DependenciesPage() {
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState<string>('')
  const [dependencies, setDependencies] = useState<Dependency[]>([])
  const [search, setSearch] = useState('')
  const [directOnly, setDirectOnly] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    getProjects()
      .then(projs => {
        setProjects(projs)
        if (projs.length > 0) {
          setSelectedProjectId(String(projs[0].id))
        }
      })
      .catch(() => setError('Failed to load projects'))
  }, [])

  useEffect(() => {
    if (!selectedProjectId) return
    setLoading(true)
    getDependencies(Number(selectedProjectId))
      .then(setDependencies)
      .catch(() => setError('Failed to load dependencies'))
      .finally(() => setLoading(false))
  }, [selectedProjectId])

  const filteredDeps = dependencies.filter(d => {
    const matchesSearch = d.name.toLowerCase().includes(search.toLowerCase()) ||
                          d.version.toLowerCase().includes(search.toLowerCase())
    const matchesDirect = directOnly ? d.is_direct : true
    return matchesSearch && matchesDirect
  })

  return (
    <div className="p-6">
      <PageHeader
        title="Software Dependencies"
        subtitle="View and manage dependency trees across projects"
      />

      {error && <ErrorBanner message={error} />}

      {/* Filters */}
      <div className="card mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-3 flex-1">
          <div className="w-64">
            <select
              className="select"
              value={selectedProjectId}
