import { useEffect, useState } from 'react'
import { AlertTriangle, ExternalLink } from 'lucide-react'
import { getProjects, getScans, getFindings, createRemediation, type Project, type Finding } from '../api/client'
import { PageHeader, Spinner, ErrorBanner, SeverityBadge, ThreatBadge } from '../components/ui'
import { THREAT_LABELS } from '../lib/constants'
import clsx from 'clsx'

export default function FindingsPage() {
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState<string>('')
  const [findings, setFindings] = useState<Finding[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [activeModalFinding, setActiveModalFinding] = useState<Finding | null>(null)
  const [remAction, setRemAction] = useState('')
  const [remTargetVer, setRemTargetVer] = useState('')
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    getProjects().then(projs => {
      setProjects(projs)
      if (projs.length > 0) setSelectedProjectId(String(projs[0].id))
    }).catch(() => setError('Failed to load projects'))
  }, [])

  useEffect(() => {
    if (!selectedProjectId) return
    setLoading(true)
    getScans(Number(selectedProjectId)).then(scans => {
      if (scans.length === 0) {
        setFindings([])
        setLoading(false)
        return
      }
      const latestScan = scans[0]
      getFindings(Number(selectedProjectId), latestScan.id)
        .then(setFindings)
        .catch(() => setError('Failed to load findings'))
        .finally(() => setLoading(false))
    }).catch(() => {
      setError('Failed to load project scans')
      setLoading(false)
    })
  }, [selectedProjectId])

  const handleCreateRemediation = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!activeModalFinding) return
    setSubmitting(true)
    try {
      await createRemediation(activeModalFinding.id, {
        action: remAction || `Upgrade ${activeModalFinding.affected_package} to ${remTargetVer || 'safe version'}`,
        target_version: remTargetVer || activeModalFinding.fixed_in_version || 'latest',
        status: 'open',
        priority: activeModalFinding.severity === 'critical' ? 1 : activeModalFinding.severity === 'high' ? 2 : 3,
      })
      setActiveModalFinding(null)
      setRemAction('')
      setRemTargetVer('')
      alert('Remediation task created successfully!')
    } catch {
      setError('Failed to create remediation task')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="p-6">
      <PageHeader
        title="Vulnerability Findings"
        subtitle="Security findings identified across latest scans"
      />

      {error && <ErrorBanner message={error} />}

      <div className="card mb-6">
        <div className="w-64">
          <label className="text-xs text-gray-400 block mb-1">Select Project</label>
          <select
            className="select"
            value={selectedProjectId}
            onChange={e => setSelectedProjectId(e.target.value)}
          >
            <option value="">Select Project</option>
            {projects.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : findings.length === 0 ? (
        <div className="card text-center py-12">
          <AlertTriangle size={36} className="text-gray-700 mx-auto mb-3" />
          <p className="text-gray-500">No vulnerability findings detected for this project's latest scan.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {findings.map(f => (
            <div key={f.id} className="card hover:border-gray-700 transition-colors">
              <div className="flex items-start justify-between gap-4">
                <div className="space-y-2 flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <SeverityBadge severity={f.severity} />
                    <ThreatBadge type={f.threat_type} />
                    <span className="text-sm font-semibold text-white">{f.title}</span>
                  </div>
                  <p className="text-xs text-gray-400">{f.description}</p>
                  <div className="flex flex-wrap gap-4 text-xs text-gray-500">
                    <span>Package: <strong className="text-sky-400 font-mono">{f.affected_package}</strong></span>
                    {f.affected_version && <span>Version: <strong className="text-gray-300 font-mono">{f.affected_version}</strong></span>}
                    {f.fixed_in_version && <span className="text-green-400 font-semibold">Fixed in: {f.fixed_in_version}</span>}
                    {f.cve_id && (
                      <a href={`https://nvd.nist.gov/vuln/detail/${f.cve_id}`} target="_blank" rel="noreferrer" className="text-sky-500 hover:underline inline-flex items-center gap-1">
                        {f.cve_id} <ExternalLink size={10} />
                      </a>
                    )}
                  </div>
                </div>
                <div className="flex flex-col items-end gap-2">
                  {f.cvss_score !== undefined && f.cvss_score !== null && (
                    <span className={clsx('text-base font-bold font-mono', f.cvss_score >= 7 ? 'text-red-400' : 'text-yellow-400')}>
                      CVSS {f.cvss_score.toFixed(1)}
                    </span>
                  )}
                  <button
                    onClick={() => setActiveModalFinding(f)}
                    className="btn-primary text-xs py-1.5 px-3"
                  >
                    Track Remediation
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Remediation Modal */}
      {activeModalFinding && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center p-4 z-50">
          <div className="card w-full max-w-md bg-gray-900 border-gray-700">
            <h3 className="text-base font-bold text-white mb-2">Create Remediation Task</h3>
            <p className="text-xs text-gray-400 mb-4">{activeModalFinding.title}</p>
            <form onSubmit={handleCreateRemediation} className="space-y-3">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Action Description</label>
                <input
                  className="input text-xs"
                  placeholder={`e.g. Upgrade ${activeModalFinding.affected_package} to secure version`}
                  value={remAction}
                  onChange={e => setRemAction(e.target.value)}
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Target Version</label>
                <input
                  className="input text-xs font-mono"
                  placeholder={activeModalFinding.fixed_in_version || 'e.g. 2.0.0'}
                  value={remTargetVer}
                  onChange={e => setRemTargetVer(e.target.value)}
                />
              </div>
              <div className="flex gap-2 justify-end pt-3">
                <button type="button" className="btn-secondary text-xs" onClick={() => setActiveModalFinding(null)}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary text-xs" disabled={submitting}>
                  {submitting ? 'Creating...' : 'Save Remediation'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Wrench, CheckCircle2, Clock, XCircle } from 'lucide-react'
import { getProjects, getScans, getFindings, getRemediations, updateRemediation, type Project, type Remediation, type Finding } from '../api/client'
import { PageHeader, Spinner, ErrorBanner } from '../components/ui'
import { formatDate } from '../lib/constants'

interface ExtendedRemediation extends Remediation {
  findingTitle?: string
  package?: string
  severity?: string
}

export default function RemediationsPage() {
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState<string>('')
  const [remediations, setRemediations] = useState<ExtendedRemediation[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    getProjects().then(projs => {
      setProjects(projs)
      if (projs.length > 0) setSelectedProjectId(String(projs[0].id))
    }).catch(() => setError('Failed to load projects'))
  }, [])

  useEffect(() => {
    if (!selectedProjectId) return
    setLoading(true)
    getScans(Number(selectedProjectId)).then(async scans => {
      if (scans.length === 0) {
        setRemediations([])
        setLoading(false)
        return
      }
      const latestScan = scans[0]
      const findings = await getFindings(Number(selectedProjectId), latestScan.id)

      const remPromises = findings.map(async f => {
        const rems = await getRemediations(f.id)
        return rems.map(r => ({
          ...r,
          findingTitle: f.title,
          package: f.affected_package,
          severity: f.severity,
        }))
      })

      const nestedRems = await Promise.all(remPromises)
      setRemediations(nestedRems.flat())
    }).catch(() => setError('Failed to load remediations'))
      .finally(() => setLoading(false))
  }, [selectedProjectId])

  const handleStatusChange = async (remId: number, status: any) => {
    try {
      await updateRemediation(remId, { status })
      setRemediations(prev => prev.map(r => r.id === remId ? { ...r, status } : r))
    } catch {
      setError('Failed to update status')
    }
  }

  return (
    <div className="p-6">
      <PageHeader
        title="Remediation Tracking"
        subtitle="Manage and track resolution of software supply chain security vulnerabilities"
      />

      {error && <ErrorBanner message={error} />}

      <div className="card mb-6">
        <div className="w-64">
          <label className="text-xs text-gray-400 block mb-1">Select Project</label>
          <select
            className="select"
            value={selectedProjectId}
            onChange={e => setSelectedProjectId(e.target.value)}
          >
            <option value="">Select Project</option>
            {projects.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : remediations.length === 0 ? (
        <div className="card text-center py-12">
          <Wrench size={36} className="text-gray-700 mx-auto mb-3" />
          <p className="text-gray-500">No active remediation tasks for this project.</p>
        </div>
      ) : (
        <div className="card overflow-hidden p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-800">
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Finding / Package</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Action</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Target Version</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Status</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Created</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Action</th>
              </tr>
            </thead>
            <tbody>
              {remediations.map(r => (
                <tr key={r.id} className="table-row">
                  <td className="py-2.5 px-4">
                    <p className="text-xs font-semibold text-white">{r.findingTitle}</p>
                    <p className="text-xs font-mono text-sky-400">{r.package}</p>
                  </td>
                  <td className="py-2.5 px-4 text-xs text-gray-300">{r.action || '—'}</td>
                  <td className="py-2.5 px-4 text-xs font-mono text-green-400">{r.target_version || '—'}</td>
                  <td className="py-2.5 px-4 text-xs">
                    <span className={`badge uppercase ${
                      r.status === 'resolved' ? 'bg-green-900/50 text-green-300 border-green-800' :
                      r.status === 'in_progress' ? 'bg-yellow-900/50 text-yellow-300 border-yellow-800' :
                      'bg-red-900/50 text-red-300 border-red-800'
                    }`}>
                      {r.status.replace('_', ' ')}
                    </span>
                  </td>
                  <td className="py-2.5 px-4 text-xs text-gray-500">{formatDate(r.created_at)}</td>
                  <td className="py-2.5 px-4 text-xs">
                    <select
                      className="bg-gray-800 border border-gray-700 rounded px-2 py-1 text-xs text-gray-200"
                      value={r.status}
                      onChange={e => handleStatusChange(r.id, e.target.value)}
                    >
                      <option value="open">Open</option>
                      <option value="in_progress">In Progress</option>
                      <option value="resolved">Resolved</option>
                      <option value="wont_fix">Won't Fix</option>
                      <option value="false_positive">False Positive</option>
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Database, ShieldCheck, ShieldAlert, CheckCircle2, XCircle } from 'lucide-react'
import { getProjects, getArtifacts, verifyArtifact, type Project, type Artifact } from '../api/client'
import { PageHeader, Spinner, ErrorBanner } from '../components/ui'
import { formatDate, formatSize } from '../lib/constants'

export default function ArtifactsPage() {
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState<string>('')
  const [artifacts, setArtifacts] = useState<Artifact[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [verifyModalArtifact, setVerifyModalArtifact] = useState<Artifact | null>(null)
  const [inputHash, setInputHash] = useState('')
  const [verifying, setVerifying] = useState(false)

  useEffect(() => {
    getProjects().then(projs => {
      setProjects(projs)
      if (projs.length > 0) setSelectedProjectId(String(projs[0].id))
    }).catch(() => setError('Failed to load projects'))
  }, [])

  useEffect(() => {
    if (!selectedProjectId) return
    setLoading(true)
    getArtifacts(Number(selectedProjectId))
      .then(setArtifacts)
      .catch(() => setError('Failed to load artifacts'))
      .finally(() => setLoading(false))
  }, [selectedProjectId])

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!verifyModalArtifact || !inputHash.trim()) return
    setVerifying(true)
    setError('')
    try {
      await verifyArtifact(Number(selectedProjectId), verifyModalArtifact.id, inputHash.trim())
      alert('Checksum verified successfully! Artifact is untampered.')
      setVerifyModalArtifact(null)
      setInputHash('')
      // refresh
      const updated = await getArtifacts(Number(selectedProjectId))
      setArtifacts(updated)
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Verification failed. Checksum mismatch detected!')
    } finally {
      setVerifying(false)
    }
  }

  return (
    <div className="p-6">
      <PageHeader
        title="Build Artifacts Repository"
        subtitle="Manage build binaries, verify cryptographic hashes, and detect artifact tampering"
      />

      {error && <ErrorBanner message={error} />}

      <div className="card mb-6">
        <div className="w-64">
          <label className="text-xs text-gray-400 block mb-1">Select Project</label>
          <select
            className="select"
            value={selectedProjectId}
            onChange={e => setSelectedProjectId(e.target.value)}
          >
            <option value="">Select Project</option>
            {projects.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <Spinner />
      ) : artifacts.length === 0 ? (
        <div className="card text-center py-12">
          <Database size={36} className="text-gray-700 mx-auto mb-3" />
          <p className="text-gray-500">No build artifacts registered for this project.</p>
        </div>
      ) : (
        <div className="card overflow-hidden p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-800">
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Artifact Name</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Type / Version</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">SHA-256 Checksum</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Signature</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Tamper Status</th>
                <th className="text-left py-3 px-4 text-xs text-gray-500 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {artifacts.map(a => (
                <tr key={a.id} className="table-row">
                  <td className="py-2.5 px-4 font-mono text-xs text-white font-semibold">{a.name}</td>
                  <td className="py-2.5 px-4 text-xs text-gray-400">{a.artifact_type || 'binary'} v{a.version || '1.0'}</td>
                  <td className="py-2.5 px-4">
                    {a.sha256 ? (
                      <span className="font-mono text-xs text-green-400" title={a.sha256}>
                        {a.sha256.slice(0, 16)}…
                      </span>
                    ) : (
                      <span className="text-xs text-yellow-500">Missing Hash</span>
                    )}
                  </td>
                  <td className="py-2.5 px-4 text-xs">
                    {a.is_signed ? (
                      <span className="text-green-400 inline-flex items-center gap-1">
                        <ShieldCheck size={13} /> Cosign Signed
                      </span>
                    ) : (
                      <span className="text-gray-500">Unsigned</span>
                    )}
                  </td>
                  <td className="py-2.5 px-4 text-xs">
                    {a.tampered ? (
                      <span className="text-red-400 font-bold inline-flex items-center gap-1">
                        <XCircle size={13} /> TAMPERED
                      </span>
                    ) : (
                      <span className="text-green-500 inline-flex items-center gap-1">
                        <CheckCircle2 size={13} /> Clean
                      </span>
                    )}
                  </td>
                  <td className="py-2.5 px-4 text-xs">
                    <button
                      onClick={() => setVerifyModalArtifact(a)}
                      className="btn-secondary text-xs py-1 px-2.5"
                    >
                      Verify Hash
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Verify Checksum Modal */}
      {verifyModalArtifact && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center p-4 z-50">
          <div className="card w-full max-w-md bg-gray-900 border-gray-700">
            <h3 className="text-base font-bold text-white mb-2">Verify Artifact Hash</h3>
            <p className="text-xs text-gray-400 mb-3">{verifyModalArtifact.name}</p>
            <form onSubmit={handleVerify} className="space-y-3">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Expected SHA-256 Hash on record</label>
                <div className="font-mono text-xs bg-gray-800 p-2 rounded text-green-400 break-all">
                  {verifyModalArtifact.sha256 || 'None'}
                </div>
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Enter Artifact Hash to Check</label>
                <input
                  className="input font-mono text-xs"
                  placeholder="Paste SHA-256 hash here..."
                  value={inputHash}
                  onChange={e => setInputHash(e.target.value)}
                  required
                />
              </div>
              <div className="flex gap-2 justify-end pt-3">
                <button type="button" className="btn-secondary text-xs" onClick={() => setVerifyModalArtifact(null)}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary text-xs" disabled={verifying}>
                  {verifying ? 'Verifying...' : 'Verify Hash Integrity'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

