@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --bg-main: #090d16;
    --bg-card: #111827;
    --border-color: #1f2937;
    --accent-glow: rgba(14, 165, 233, 0.15);
  }

  body {
    @apply bg-[#090d16] text-gray-100 antialiased font-sans selection:bg-sky-500/30 selection:text-sky-200;
  }

  * {
    @apply border-gray-800/80;
  }

  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    @apply bg-[#090d16];
  }
  ::-webkit-scrollbar-thumb {
    @apply bg-gray-800 rounded-full hover:bg-gray-700 transition-colors;
  }
}

@layer components {
  /* High-end glass card with hover glow */
  .card {
    @apply bg-gray-900/90 backdrop-blur-md border border-gray-800/80 rounded-xl p-5 
           shadow-xl shadow-black/20 hover:border-gray-700/80 transition-all duration-200;
  }

  .card-glow {
    @apply card relative overflow-hidden before:absolute before:inset-0 
           before:bg-gradient-to-r before:from-sky-500/10 before:to-purple-500/10 
           before:opacity-0 hover:before:opacity-100 before:transition-opacity before:pointer-events-none;
  }

  /* Sleek Badges */
  .badge {
    @apply inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-[11px] font-semibold tracking-wider uppercase border;
  }

  .badge-critical {
    @apply badge bg-red-950/60 text-red-400 border-red-800/60 shadow-sm shadow-red-950/50;
  }
  .badge-high {
    @apply badge bg-orange-950/60 text-orange-400 border-orange-800/60 shadow-sm shadow-orange-950/50;
  }
  .badge-medium {
    @apply badge bg-amber-950/60 text-amber-400 border-amber-800/60 shadow-sm shadow-amber-950/50;
  }
  .badge-low {
    @apply badge bg-sky-950/60 text-sky-400 border-sky-800/60 shadow-sm shadow-sky-950/50;
  }
  .badge-none {
    @apply badge bg-emerald-950/60 text-emerald-400 border-emerald-800/60;
  }

  /* Styled Buttons */
  .btn-primary {
    @apply inline-flex items-center justify-center gap-2 px-4 py-2 
           bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-400 hover:to-blue-500 
           text-white text-xs font-semibold rounded-lg shadow-lg shadow-sky-500/25 
           transition-all duration-150 active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none;
  }

  .btn-secondary {
    @apply inline-flex items-center justify-center gap-2 px-3.5 py-1.5 
           bg-gray-800/80 hover:bg-gray-700/90 text-gray-200 text-xs font-medium 
           rounded-lg border border-gray-700/80 transition-all duration-150 active:scale-[0.98];
  }

  .btn-danger {
    @apply inline-flex items-center justify-center gap-2 px-3.5 py-1.5 
           bg-red-600/90 hover:bg-red-500 text-white text-xs font-semibold 
           rounded-lg shadow-lg shadow-red-600/20 transition-all duration-150 active:scale-[0.98];
  }

  /* Inputs & Selects */
  .input {
    @apply w-full bg-gray-950/80 border border-gray-800 rounded-lg px-3.5 py-2 text-xs 
           text-gray-100 placeholder-gray-500 focus:outline-none focus:ring-2 
           focus:ring-sky-500/50 focus:border-sky-500 transition-all;
  }

  .select {
    @apply input appearance-none cursor-pointer bg-no-repeat pr-8;
  }

  .table-row {
    @apply border-b border-gray-800/60 hover:bg-gray-800/40 transition-colors duration-150;
  }
}

import { Shield, LayoutDashboard, FolderGit2, Package, Search, FileText, Wrench, AlertTriangle, Database, Activity } from 'lucide-react'
import { Link, useLocation } from 'react-router-dom'
import clsx from 'clsx'

const NAV = [
  { to: '/',            icon: LayoutDashboard, label: 'Dashboard' },
  { to: '/projects',    icon: FolderGit2,      label: 'Projects' },
  { to: '/dependencies',icon: Package,         label: 'Dependencies' },
  { to: '/scans',       icon: Search,          label: 'Security Scans' },
  { to: '/findings',    icon: AlertTriangle,   label: 'Vulnerabilities' },
  { to: '/remediations',icon: Wrench,          label: 'Remediations' },
  { to: '/artifacts',   icon: Database,        label: 'Artifact Store' },
  { to: '/reports',     icon: FileText,        label: 'Risk Reports' },
  { to: '/threat-intel',icon: Shield,          label: 'Threat Intel' },
]

export default function Sidebar() {
  const { pathname } = useLocation()

  return (
    <aside className="w-64 min-h-screen bg-[#0d1322] border-r border-gray-800/80 flex flex-col flex-shrink-0">
      {/* Brand Header */}
      <div className="px-5 py-6 border-b border-gray-800/80">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-sky-500 to-blue-600 flex items-center justify-center flex-shrink-0 shadow-lg shadow-sky-500/25">
            <Shield size={18} className="text-white" />
          </div>
          <div>
            <div className="text-sm font-bold text-white tracking-wide flex items-center gap-1.5">
              SecureChain <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            </div>
            <div className="text-[11px] text-sky-400 font-medium">Supply Chain Security</div>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-3 py-5 space-y-1">
        <div className="px-3 pb-2 text-[10px] font-semibold uppercase tracking-wider text-gray-500">
          Core Workflows
        </div>
        {NAV.map(({ to, icon: Icon, label }) => {
          const active = pathname === to || (to !== '/' && pathname.startsWith(to))
          return (
            <Link
              key={to}
              to={to}
              className={clsx(
                'flex items-center gap-3 px-3 py-2.5 rounded-lg text-xs font-medium transition-all duration-150 group relative',
                active
                  ? 'bg-sky-500/10 text-sky-400 font-semibold border border-sky-500/20 shadow-sm'
                  : 'text-gray-400 hover:text-gray-100 hover:bg-gray-800/60'
              )}
            >
              {active && (
                <span className="absolute left-0 top-1.5 bottom-1.5 w-1 rounded-r-full bg-sky-500 shadow-sm shadow-sky-500" />
              )}
              <Icon size={16} className={clsx('flex-shrink-0 transition-colors', active ? 'text-sky-400' : 'text-gray-500 group-hover:text-gray-300')} />
              <span>{label}</span>
            </Link>
          )
        })}
      </nav>

      {/* Footer Info */}
      <div className="p-4 border-t border-gray-800/80 bg-gray-950/40">
        <div className="flex items-center gap-2 text-xs text-gray-400 mb-1">
          <Activity size={12} className="text-emerald-400" />
          <span className="font-semibold text-gray-300">Scanner Engine</span>
        </div>
        <div className="text-[11px] text-gray-500">v1.0.0 · Active Monitoring</div>
      </div>
    </aside>
  )
}

"""
SecureChain — Authentication & Authorization Module (Phase 12 Secure Module)
Implements JWT tokens, password hashing with bcrypt, input validation, RBAC authorization, and safe error responses.
"""
from datetime import datetime, timedelta
from typing import Optional
from fastapi import APIRouter, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from passlib.context import CryptContext
from pydantic import BaseModel, EmailStr, Field
from jose import JWTError, jwt

# ── Security Configurations ─────────────────────
SECRET_KEY = "securechain-super-secret-key-change-in-prod"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 60

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/login")

router = APIRouter(prefix="/auth", tags=["Authentication & Authorization"])


# ── Schemas with Strict Input Validation ────────

class UserRegister(BaseModel):
    username: str = Field(..., min_length=3, max_length=50, pattern=r"^[a-zA-Z0-9_-]+$")
    email: EmailStr
    password: str = Field(..., min_length=8, max_length=128)
    role: str = Field("Student", pattern=r"^(Student|Faculty|Administrator|SecurityAnalyst)$")


class UserOut(BaseModel):
    username: str
    email: EmailStr
    role: str
    is_active: bool = True


class Token(BaseModel):
    access_token: str
    token_type: str = "bearer"
    role: str


# ── In-Memory Security Store (Demo) ────────────

FAKE_USERS_DB = {
    "admin": {
        "username": "admin",
        "email": "admin@securechain.edu",
        "hashed_password": pwd_context.hash("AdminPass123!"),
        "role": "Administrator",
        "is_active": True,
    },
    "student_dev": {
        "username": "student_dev",
        "email": "student@securechain.edu",
        "hashed_password": pwd_context.hash("StudentPass123!"),
        "role": "Student",
        "is_active": True,
    }
}


# ── Security Helper Functions ───────────────────

def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)


def create_access_token(data: dict, expires_delta: Optional[timedelta] = None) -> str:
    to_encode = data.copy()
    expire = datetime.utcnow() + (expires_delta or timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES))
    to_encode.update({"exp": expire})
    return jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)


def get_current_user(token: str = Depends(oauth2_scheme)) -> UserOut:
    credentials_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Could not validate credentials",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get("sub")
        if username is None or username not in FAKE_USERS_DB:
            raise credentials_exception
        user_dict = FAKE_USERS_DB[username]
        return UserOut(
            username=user_dict["username"],
            email=user_dict["email"],
            role=user_dict["role"],
            is_active=user_dict["is_active"],
        )
    except JWTError:
        raise credentials_exception


def require_role(allowed_roles: list[str]):
    """RBAC Dependency enforcement."""
    def role_checker(current_user: UserOut = Depends(get_current_user)):
        if current_user.role not in allowed_roles:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail=f"Access denied. User role '{current_user.role}' lacks required permissions."
            )
        return current_user
    return role_checker


# ── Auth Endpoints ──────────────────────────────

@router.post("/register", response_model=UserOut, status_code=status.HTTP_201_CREATED)
def register_user(payload: UserRegister):
    if payload.username in FAKE_USERS_DB:
        raise HTTPException(status_code=400, detail="Username already registered")

    hashed_pwd = pwd_context.hash(payload.password)
    user_entry = {
        "username": payload.username,
        "email": payload.email,
        "hashed_password": hashed_pwd,
        "role": payload.role,
        "is_active": True,
    }
    FAKE_USERS_DB[payload.username] = user_entry
    return UserOut(**user_entry)


@router.post("/login", response_model=Token)
def login_user(form_data: OAuth2PasswordRequestForm = Depends()):
    user = FAKE_USERS_DB.get(form_data.username)
    if not user or not verify_password(form_data.password, user["hashed_password"]):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    access_token = create_access_token(data={"sub": user["username"], "role": user["role"]})
    return Token(access_token=access_token, token_type="bearer", role=user["role"])


@router.get("/me", response_model=UserOut)
def read_current_user(current_user: UserOut = Depends(get_current_user)):
    return current_user


@router.get("/admin-only", dependencies=[Depends(require_role(["Administrator", "Faculty"]))])
def admin_protected_route():
    return {"message": "Access granted to Administrator/Faculty management portal."}
